struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int v) : val(v), left(nullptr), right(nullptr) {}
};

TreeNode* insert(TreeNode* root, int val) {
    if (root == nullptr) return new TreeNode(val);

    if (val < root->val) {
        root->left = insert(root->left, val);
    } else if (val > root->val) {
        root->right = insert(root->right, val);
    }
    // duplicates are ignored here, decide your own policy if needed

    return root;
}

TreeNode* search(TreeNode* root, int val) {
    if (root == nullptr || root->val == val) return root;

    if (val < root->val) return search(root->left, val);
    return search(root->right, val);
}

TreeNode* findMin(TreeNode* node) {
    while (node->left != nullptr) node = node->left;
    return node;
}

TreeNode* deleteNode(TreeNode* root, int key) {
    if (root == nullptr) return nullptr;

    if (key < root->val) {
        root->left = deleteNode(root->left, key);
    } else if (key > root->val) {
        root->right = deleteNode(root->right, key);
    } else {
        // this is the node to delete

        // Case 1: leaf node
        if (root->left == nullptr && root->right == nullptr) {
            delete root;
            return nullptr;
        }

        // Case 2: one child
        if (root->left == nullptr) {
            TreeNode* temp = root->right;
            delete root;
            return temp;
        }
        if (root->right == nullptr) {
            TreeNode* temp = root->left;
            delete root;
            return temp;
        }

        // Case 3: two children, use the in-order successor
        TreeNode* successor = findMin(root->right);
        root->val = successor->val;
        root->right = deleteNode(root->right, successor->val);
    }
    return root;
}

void inorder(TreeNode* root, vector<int>& result) {
    if (root == nullptr) return;

    inorder(root->left, result);
    result.push_back(root->val);
    inorder(root->right, result);
}

struct OSNode {
    int val;
    int size;         // size of the subtree rooted here, including this node
    OSNode* left;
    OSNode* right;
};

int kthSmallest(OSNode* root, int k) {
    int leftSize = root->left ? root->left->size : 0;

    if (k <= leftSize) return kthSmallest(root->left, k);
    if (k == leftSize + 1) return root->val;
    return kthSmallest(root->right, k - leftSize - 1);
}

#include <set>
#include <iostream>
using namespace std;

int main() {
    set<int> s = {30, 10, 50, 20, 40};   // stored sorted automatically

    for (int x : s) cout << x << " ";    // prints: 10 20 30 40 50
    cout << endl;

    auto it1 = s.lower_bound(25);        // first element >= 25
    cout << "lower_bound(25) = " << *it1 << endl;

    auto it2 = s.upper_bound(30);        // first element > 30
    cout << "upper_bound(30) = " << *it2 << endl;

    if (s.find(20) != s.end()) cout << "found 20" << endl;

    s.erase(30);
    cout << "after erasing 30, size = " << s.size() << endl;
    return 0;
}

#include <set>
#include <iostream>
using namespace std;

int main() {
    multiset<int> ms = {10, 20, 20, 20, 30, 40};

    cout << "count of 20 = " << ms.count(20) << endl;   // 3

    auto range = ms.equal_range(20);
    cout << "all 20s: ";
    for (auto it = range.first; it != range.second; ++it) cout << *it << " ";
    cout << endl;

    ms.erase(ms.find(20));   // erase exactly one occurrence of 20
    cout << "count of 20 after single erase = " << ms.count(20) << endl;  // 2
    return 0;
}
